const baseUrl = (process.env.CICERONE_SERVE_URL || "http://localhost:8000").replace(/\/$/, "");
const token = process.env.CICERONE_SERVE_TOKEN;
if (!token) {
  console.error("Set CICERONE_SERVE_TOKEN to a bearer token");
  process.exit(1);
}
const userId = process.env.CICERONE_USER_ID || "alice";

async function main() {
  const response = await fetch(`${baseUrl}/events`, {
    method: "POST",
    headers: {
      Accept: "application/json",
      Authorization: `Bearer ${token}`,
      "Content-Type": "application/json",
    },
    body: JSON.stringify({
      user_id: userId,
      item_id: "ipa-001",
      event_type: "purchase",
      quantity: 1,
      occurred_at: "2026-08-19T12:00:00Z",
    }),
  });
  if (!response.ok) throw new Error(`${response.status} ${await response.text()}`);
  console.log(await response.json());
}

main().catch((err) => {
  console.error(err);
  process.exitCode = 1;
});

